from common import *
import html,copy
from backtest.scripts.register.experiment_registry import append_registry
from backtest.scripts.maintenance.experiment_archive import _validate_metadata
NAMES={'v5':'当前baseline v5 · H20旧标签10档','h7continuous':'H7连续标签 · 同源对照','h15continuous':'H15连续标签 · 同源对照','h20continuous':'H20连续标签 · 同源对照','h20q10':'H20 10档 · 同源对照','h7q10':'H7 10档','h15q10':'H15 10档','sum20continuous':'H1～H20原始累计收益和 · 连续','sum20q10':'H1～H20原始累计收益和 · 10档'}
ORDER=['v5','h7continuous','h7q10','h15continuous','h15q10','h20continuous','h20q10','sum20continuous','sum20q10']
KEYS=[('net_ann','扣费净年化'),('net_ann_vol','扣费波动'),('net_sharpe','扣费夏普'),('ann','未扣费年化'),('turnover','日换手')]
def path(name):return BASE/'metrics'/(name+'-new.json' if name in VARIANTS else name+'.json')
def official(d):return d['pools']['all']['ensemble']
def cell(d,style=None):
 e=official(d);return e['head']['3']['5'] if style is None else e['head_regimes'][style]['3']['5']
def fmt(v,k):return '—' if v is None else (f'{v:.4f}' if k in ['net_sharpe','rank_ic_mean'] else f'{v:.2%}')
def render():
 state=read(PROGRESS);docs={n:read(path(n)) for n in ORDER if path(n).exists()}
 summary={'status':'completed' if all(v in docs for v in VARIANTS) else 'running','completed_candidates':[v for v in VARIANTS if v in docs],'actual_fit_starts':len(state['jobs']),'successful_fits':sum(j['status']=='succeeded' for j in state['jobs']),'prior_fits':PRIOR_FITS,'cumulative_fits':PRIOR_FITS+len(state['jobs']),'primary':{n:{**cell(d),'rank_ic_mean':official(d)['h5']['rank_ic_mean']} for n,d in docs.items()},'style_pairs':{},'horizon_maxima':{},'sum_comparisons':{},'early_stopping':[],'seed_diagnostics':{}}
 for h in [7,15,20]:
  a,b=f'h{h}q10',f'h{h}continuous'
  if a in docs and b in docs:
   summary['style_pairs'][str(h)]={r:{k:cell(docs[a],r)[k]-cell(docs[b],r)[k] for k,_ in KEYS[:3]} for r in ['D','F','T']}
 summary['paired_seed_style']={}
 summary['paired_year_changes']={}
 for h in [7,15,20]:
  a,b=f'h{h}q10',f'h{h}continuous'
  if a not in docs or b not in docs:continue
  summary['paired_seed_style'][str(h)]={}
  for regime in ['D','F','T']:
   summary['paired_seed_style'][str(h)][regime]={}
   for key in ['net_ann','net_sharpe']:
    differences={str(seed):docs[a]['pools']['all']['seeds'][str(seed)]['head_regimes'][regime]['3']['5'][key]-docs[b]['pools']['all']['seeds'][str(seed)]['head_regimes'][regime]['3']['5'][key] for seed in SEEDS}
    summary['paired_seed_style'][str(h)][regime][key]={'differences':differences,'positive':sum(v>1e-12 for v in differences.values()),'negative':sum(v<-1e-12 for v in differences.values())}
  summary['paired_year_changes'][str(h)]={year:{key:official(docs[a])['head_years'][year]['3']['5'][key]-official(docs[b])['head_years'][year]['3']['5'][key] for key in ['net_ann','net_sharpe']} for year in [str(y) for y in range(2020,2027)]}
 if len(summary['style_pairs'])==3:
  summary['universality']={r:{k:{'positive':sum(summary['style_pairs'][str(h)][r][k]>1e-12 for h in [7,15,20]),'negative':sum(summary['style_pairs'][str(h)][r][k]<-1e-12 for h in [7,15,20]),'zero':sum(abs(summary['style_pairs'][str(h)][r][k])<=1e-12 for h in [7,15,20])} for k in ['net_ann','net_sharpe']} for r in ['D','F','T']}
  summary['T_return_weaker_all_three']=summary['universality']['T']['net_ann']['negative']==3
  summary['D_return_stronger_all_three']=summary['universality']['D']['net_ann']['positive']==3
 for typ in ['continuous','q10']:
  if all(f'h{h}{typ}' in docs for h in [7,15,20]):
   summary['horizon_maxima'][typ]={r:{k:[h for h in [7,15,20] if abs(cell(docs[f'h{h}{typ}'],r)[k]-max(cell(docs[f'h{x}{typ}'],r)[k] for x in [7,15,20]))<=1e-12] for k in ['net_ann','net_sharpe']} for r in ['D','F','T']}
 for a,b in [('sum20continuous','h20continuous'),('sum20q10','h20q10'),('sum20q10','sum20continuous')]:
  if a in docs and b in docs:
   summary['sum_comparisons'][a+' minus '+b]={'full':{k:cell(docs[a])[k]-cell(docs[b])[k] for k,_ in KEYS[:3]},'styles':{r:{k:cell(docs[a],r)[k]-cell(docs[b],r)[k] for k,_ in KEYS[:3]} for r in ['D','F','T']}}
 for n,d in docs.items():
  seeds=d['pools']['all']['seeds'];diag={}
  for k in ['net_ann','net_sharpe']:
   vals=[seeds[str(s)]['head']['3']['5'][k] for s in SEEDS];diag[k]={'seed_min':min(vals),'seed_max':max(vals),'ensemble':cell(d)[k],'ensemble_below_all':cell(d)[k]<min(vals)}
  summary['seed_diagnostics'][n]=diag
 for job in state['jobs']:
  if job['status']!='succeeded':continue
  r=read(BASE/'docs'/f'{job["job_id"]}.json');es=r['early_stopping'][0]
  row={'candidate':job['variant'],'seed':job['seed'],'best_iteration':es['best_iteration'],'observed_rounds':len(r['rounds']),'selected_boundary_ties':r['selected_boundary_ties'],'fit_seconds':r['fit_seconds'],'max_rss_GiB':r['max_rss_bytes']/1024**3}
  summary['early_stopping'].append(row)
 write(BASE/'docs/study-summary.json',summary)
 css='body{font-family:-apple-system,"PingFang SC",sans-serif;background:#f6f7f9;color:#172b3a;margin:0}main{max-width:1300px;margin:auto;padding:28px}h1{font-size:25px}h2{font-size:19px;margin-top:28px}p{line-height:1.7}.note{color:#5e6b79;font-size:13px}.scroll{overflow:auto}table{border-collapse:collapse;background:white;width:100%;font-size:13px}td,th{border:1px solid #dce3e9;padding:8px;text-align:right}th{background:#edf2f7}td:first-child,th:first-child{text-align:left}a{color:#125dac}'
 H=['<!doctype html><html lang="zh"><meta charset="utf-8"><title>路径收益和与10档期限实验</title><style>'+css+'</style><main><h1>路径收益和与10档期限实验</h1>',f'<p>状态：{summary["status"]}；四组中 {len(summary["completed_candidates"])} 组已评估，实际 {len(state["jobs"])} 次训练启动，成功 {summary["successful_fits"]} 次；前序累计176次。平台代表为事先指定的求和20/10档，不代表事后最优方案。</p>','<p>统一Alpha158+range、M0样本日期/权重、五种子[42,1000,2000,3000,4000]、Top5×H5早停、patience50和200轮上限。官方指标为五种子逐日z-score均值信号的Top3×H5；2020-08-03～2026-07-31历史选型窗，H5信号截止2026-07-23（1448日），不是独立样本外。</p>','<h2>标签定义与样本</h2>','<p>新H20标签先计算 Σ(k=1…20)[Close(t+k+1)/Close(t+1)−1]，再按日截面CSRankNorm；连续版不分档，10档版使用等样本中秩边界和当前v5固定仿射编码，分档后不再次排名。按用户补充要求，保留原H20有效样本，缺失中间项直接跳过，不补价、不按有效项数归一化；原始严格完整路径准备已停止且未启动任何训练。</p>','<p>H7/H15分档各自保留原有有效样本；H20正式v5使用旧标签来源，同源期限比较另用Nov3 H20连续与10档对照，不能把新旧来源差异当作分档效果。求和标签倾向较早/持续上涨，不保证低波动样本必排在前面。</p>']
 mechanism=BASE/'docs/label-mechanism.json'
 if mechanism.exists():
  m=read(mechanism);H.append('<p class="note">训练内机制诊断：有效求和项数分布 '+html.escape(json.dumps(m['observed_horizon_counts'],ensure_ascii=False))+'；在每日H20终点收益十分位内，求和排名与可观察日收益波动排名的条件相关为 '+format(m['conditional_rank_correlation_sum_vs_vol'],'.4f')+'。该诊断不参与选型；缺失相邻价格的日收益不进入波动统计。</p>')
 def table(title,cols,rows):
  H.append('<h2>'+html.escape(title)+'</h2><div class="scroll"><table><tr>'+''.join('<th>'+html.escape(c)+'</th>' for c in cols)+'</tr>')
  for row in rows:H.append('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>')
  H.append('</table></div>')
 table('全窗官方主格',['方案',*[x[1] for x in KEYS],'全局H5 RankIC'],[[NAMES[n],*[fmt(cell(d).get(k),k) for k,_ in KEYS],fmt(official(d)['h5']['rank_ic_mean'],'rank_ic_mean')] for n,d in docs.items()])
 if summary['style_pairs']:
  table('10档减连续：同源逐期限变化',['H','风格','净年化差（百分点）','夏普差','波动差（百分点）'],[[h,r,f'{v["net_ann"]*100:+.2f}',f'{v["net_sharpe"]:+.4f}',f'{v["net_ann_vol"]*100:+.2f}'] for h,styles in summary['style_pairs'].items() for r,v in styles.items()])
 if summary['paired_seed_style']:
  table('逐种子同向性 · 10档相对连续',['H','风格','收益改善种子/5','收益下降种子/5','夏普改善种子/5','夏普下降种子/5'],[[h,r,str(v['net_ann']['positive']),str(v['net_ann']['negative']),str(v['net_sharpe']['positive']),str(v['net_sharpe']['negative'])] for h,styles in summary['paired_seed_style'].items() for r,v in styles.items()])
 if 'universality' in summary:
  H.append('<h2>预先定义的判断</h2><p>三个已测期限T收益都下降：'+str(summary['T_return_weaker_all_three'])+'；三个已测期限D收益都上升：'+str(summary['D_return_stronger_all_three'])+'。只覆盖H7/H15/H20，收益与夏普分别判断，不以均值代替“全部”。</p>')
  table('各风格收益/夏普最大期限（列出并列）',['编码','风格','净年化最高H','夏普最高H'],[[typ,r,str(v['net_ann']),str(v['net_sharpe'])] for typ,styles in summary['horizon_maxima'].items() for r,v in styles.items()])
 if summary['sum_comparisons']:
  table('求和标签的配对变化',['比较','净年化差（百分点）','夏普差','波动差（百分点）'],[[n,f'{v["full"]["net_ann"]*100:+.2f}',f'{v["full"]["net_sharpe"]:+.4f}',f'{v["full"]["net_ann_vol"]*100:+.2f}'] for n,v in summary['sum_comparisons'].items()])
 for block,title,cols in [('head_regimes','分风格',['D','F','T']),('head_years','分年',[str(y) for y in range(2020,2027)])]:
  for k,label in KEYS[:3]:table(title+' · '+label,['方案',*cols],[[NAMES[n],*[fmt(official(d)[block][c]['3']['5'].get(k),k) for c in cols]] for n,d in docs.items()])
 table('逐种子训练核验',['方案','seed','最佳轮','观察轮','选中轮Top3/5同分日','训练秒','进程峰值GiB'],[[NAMES[r['candidate']],str(r['seed']),str(r['best_iteration']),str(r['observed_rounds']),str(r['selected_boundary_ties']),str(round(r['fit_seconds'])),f'{r["max_rss_GiB"]:.2f}'] for r in summary['early_stopping']])
 H.append('<p class="note">模型净年化为×238/5算术口径、波动为HAC；不是执行账户CAGR。F仅136日/2024年7个月，不作跨年泛化结论。保持全部五种子，不改早停、策略、正式基线或生产配置。</p><p><a href="../configs/frozen-study.json">初始冻结方案</a> · <a href="../configs/missing-price-amendment.json">用户缺失价格规则补充</a> · <a href="../configs/prepared-inputs.json">标签来源/实际样本</a> · <a href="../docs/study-summary.json">数值摘要</a> · <a href="../docs/study-progress.json">逐作业状态</a> · <a href="../docs/harness-state.json">正式状态</a></p></main></html>')
 (BASE/'reports/detail.html').write_text('\n'.join(H))
 return summary,docs
def main():
 save_source(__file__);summary,docs=render();progress=read(PROGRESS)
 complete=summary['status']=='completed';plan=read(BASE/'configs/frozen-study.json')
 records=[]
 for name,doc in docs.items():
  record={'candidate':name,'exp_id':EID+'/arms/'+name,'parent_experiment':EID,'state':'completed','source_role':'internal_scientific_candidate' if name in VARIANTS else 'reused_control','seeds':SEEDS,'eval_output':fingerprint(path(name)),'metrics':summary['primary'][name]}
  out=BASE/'docs'/f'candidate-{name}-record.json';write(out,record);records.append(fingerprint(out))
 row={'exp_id':EID,'archive_path':str(BASE.relative_to(ROOT)),'date':'2026-11-07','state':'completed' if complete else 'running','phase':'M','phase_m_protocol':'v1','direction':'training-target','experiment_type':'training_target','display_name':'路径累计收益和与10档期限对照 · patience50','hypothesis':plan['hypothesis'],'baseline_ref':BASELINE_ID,'data_version':'2026-11-03','seeds':SEEDS,'train_pool':'all','test_pools':['all'],'evaluation_mode':'historical_selection_window','detail_report':str((BASE/'reports/detail.html').relative_to(ROOT)),'representative_candidate':REPRESENTATIVE+' predeclared, not a selected winner','internal_candidate_records':records,'execution_audit':{'scientific_candidates':4,'actual_new_fits':len(progress['jobs']),'successful_fits':summary['successful_fits'],'prior_fits':PRIOR_FITS,'cumulative_fits':PRIOR_FITS+len(progress['jobs'])},'configs':[str((BASE/'configs'/f).relative_to(ROOT)) for f in ['frozen-study.json','missing-price-amendment.json','prepared-inputs.json','harness-plan.json','evaluation.yaml']],'result_dirs':[str(Path('backtest/result')/j['session']) for j in progress['jobs'] if j['status']=='succeeded']+['backtest/result/20261107_pathsum_quantile10'],'harness':{'campaign_id':'pathsum-quantile10-p50-20261107-v1','attempt_id':read(STATE)['variants'][EID]['attempts'][-1]['attempt_id']},'conclusion':f'{len(summary["completed_candidates"])}/4组已完成；逐期限/风格配对及求和标签比较见详情，未晋升。','study_summary':str((BASE/'docs/study-summary.json').relative_to(ROOT)),'diagnostic_only':True,'cleanup_retention_eligible':False}
 if REPRESENTATIVE in docs:row.update(eval_output=str(path(REPRESENTATIVE).relative_to(ROOT)),portable_eval_output=str(path(REPRESENTATIVE).relative_to(ROOT)),metrics=summary['primary'][REPRESENTATIVE])
 meta=read(BASE/'metadata.json');meta['analysis']={'conclusion':row['conclusion'],'evidence':['reports/detail.html','docs/study-summary.json'],'limitations':'历史选型窗口；缺失中间收益跳过但不缩放；同源H20与当前旧标签v5分开。平台代表求和20/10档，不是综合或优胜指标。','review_status':'draft','updated_at':'2026-11-07'};write(BASE/'metadata.json',meta);_validate_metadata(ROOT,BASE/'metadata.json',meta,'model')
 append_registry(ROOT/'backtest/experiments/registry.jsonl',row)
 subprocess.run([sys.executable,str(ROOT/'backtest/scripts/report/build_phase_m_v1_report.py')],cwd=ROOT,check=True)
 for v in VARIANTS:
  if v in docs:progress['scientific_candidates'][v]['status']='completed'
 progress['status']='evaluated' if complete else 'running'
 progress.setdefault('registration_receipts',[]).append({'completed_candidates':summary['completed_candidates'],'registry':fingerprint(ROOT/'backtest/experiments/registry.jsonl'),'detail':fingerprint(BASE/'reports/detail.html'),'summary':fingerprint(BASE/'docs/study-summary.json'),'candidate_records':records})
 write(PROGRESS,progress);print('Registered/reported',len(summary['completed_candidates']),'of4 groups',flush=True)
if __name__=='__main__':main()
